import{U as e,gt as t,nt as n,rt as r}from"./chunks/framework.B3obAz7o.js";var i=JSON.parse(`{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md","lastUpdated":1785228915000}`),a={name:`troubleshooting.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h1><p>Start by recording the installed version, Node.js version, operating system, CPU architecture, requested runtime, input format, and complete diagnostic. <code>fontmin-rs inspect &lt;font&gt; --json</code> provides a machine-readable input summary.</p><h2 id="native-binding-cannot-load" tabindex="-1">Native binding cannot load <a class="header-anchor" href="#native-binding-cannot-load" aria-label="Permalink to “Native binding cannot load”">​</a></h2><p>The published <code>fontmin-rs</code> package keeps native platform packages optional. Confirm that optional dependencies were not disabled and that the current platform appears in the <a href="./support">support matrix</a>.</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input-type=module</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;import{readFileSync}from&#39;node:fs&#39;;import{inspect}from&#39;fontmin-rs&#39;;console.log(inspect(readFileSync(process.argv[1])))&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  path/to/font.ttf</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Use <code>runtime: &quot;auto&quot;</code> when WASM fallback is acceptable. Use <code>runtime: &quot;native&quot;</code> when a missing native package must fail immediately. Do not copy a <code>.node</code> file between operating systems, CPU architectures, libc variants, or Node-API package versions.</p><h2 id="wasm-fallback-fails" tabindex="-1">WASM fallback fails <a class="header-anchor" href="#wasm-fallback-fails" aria-label="Permalink to “WASM fallback fails”">​</a></h2><p>The Node package requires the <code>@fontmin-rs/wasm</code> dependency. Reinstall from the lockfile and check that bundler rules did not exclude <code>.wasm</code> assets. Browser code must import <code>@fontmin-rs/wasm</code> directly and use its asynchronous, memory-only API; filesystem paths and Node plugin hooks are not available.</p><h2 id="configuration-is-not-found-or-rejected" tabindex="-1">Configuration is not found or rejected <a class="header-anchor" href="#configuration-is-not-found-or-rejected" aria-label="Permalink to “Configuration is not found or rejected”">​</a></h2><p>Run the CLI from the intended project directory or pass <code>--config</code> explicitly. Executable TypeScript, MTS, MJS, and CJS configuration requires Node.js 22 or newer. Unknown fields and runtime/fallback conflicts are errors by design. Compare the resolved shape with the <a href="./guide/config">configuration reference</a>.</p><h2 id="a-font-is-rejected" tabindex="-1">A font is rejected <a class="header-anchor" href="#a-font-is-rejected" aria-label="Permalink to “A font is rejected”">​</a></h2><p>First run <code>inspect</code> and <code>coverage</code> separately. A stable <code>invalid-font</code>, <code>unsupported</code>, or missing-glyph diagnostic is preferable to retrying the same input through a different output format. Reduce confidential inputs before sharing them; malformed inputs that expose a parser failure can be reported privately under the <a href="https://github.com/fontmin-rs/fontmin-rs/security/policy" target="_blank" rel="noreferrer">security policy</a>.</p><h2 id="output-differs-from-classic-fontmin" tabindex="-1">Output differs from classic Fontmin <a class="header-anchor" href="#output-differs-from-classic-fontmin" aria-label="Permalink to “Output differs from classic Fontmin”">​</a></h2><p>Compare parsed metadata, requested glyph coverage, CSS semantics, and file naming. Byte-for-byte equality is not a compatibility promise. The <a href="./guide/migration">migration guide</a> lists intentional API differences, and the <a href="./benchmarks">performance policy</a> explains the representative paired benchmark.</p><h2 id="reporting-a-reproducible-problem" tabindex="-1">Reporting a reproducible problem <a class="header-anchor" href="#reporting-a-reproducible-problem" aria-label="Permalink to “Reporting a reproducible problem”">​</a></h2><p>For ordinary bugs, open a GitHub issue with the smallest redistributable font or synthetic reproducer and the information listed at the top of this page. For a suspected vulnerability, use private vulnerability reporting instead of a public issue.</p>`,16)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};